using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n);
    for (int &x : a) cin >> x;

    while (!a.empty() && a.back() == 0)
        a.pop_back();

    int l = 0;
    for (size_t i = 0; i + 1 < a.size(); ++i) {
        if (a[i] == 0 && a[i + 1] == 0)
            ++i;
        ++l;
    }

    cout << l;
    return 0;
}

